import {spawn} from 'node:child_process';
let child,stopping=false,failures=0;
function start(){const started=Date.now();child=spawn(process.execPath,['server.mjs'],{stdio:'inherit',env:process.env});child.on('exit',()=>{if(stopping)return;failures=Date.now()-started>60000?0:failures+1;setTimeout(start,Math.min(30000,1000*2**Math.min(failures,5)));});}
for(const signal of ['SIGTERM','SIGINT'])process.on(signal,()=>{stopping=true;child?.kill(signal);setTimeout(()=>process.exit(0),8000).unref();});start();

